#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y, l, r;
    if (!(cin >> x >> y >> l >> r)) return 0;

    const long long INF = (long long)4e18;
    vector<long long> powx, powy;

    // generate powers of x
    {
        long long v = 1;
        while (true) {
            powx.push_back(v);
            if (v > INF / x) break;
            v *= x;
        }
    }
    // generate powers of y
    {
        long long v = 1;
        while (true) {
            powy.push_back(v);
            if (v > INF / y) break;
            v *= y;
        }
    }

    set<long long> unlucky;
    for (long long a : powx) {
        for (long long b : powy) {
            long long s = a + b;
            if (s > r) break;
            if (s >= l) unlucky.insert(s);
        }
    }

    if (unlucky.empty()) {
        cout << (r - l + 1) << '\n';
        return 0;
    }

    vector<long long> v(unlucky.begin(), unlucky.end());
    long long ans = 0;

    // segment before first unlucky
    if (v[0] > l) ans = max(ans, v[0] - l);

    // segments between unlucky years
    for (size_t i = 1; i < v.size(); ++i) {
        long long left = v[i - 1] + 1;
        long long right = v[i] - 1;
        if (right >= left) ans = max(ans, right - left + 1);
    }

    // segment after last unlucky
    if (v.back() < r) ans = max(ans, r - v.back());

    cout << ans << '\n';
    return 0;
}

